const r = await tools.exec_command({cmd:"python - <<'PY'
import json,numpy as np
j=json.load(open('/app/output/jacobian.json'))['J'];J=np.array(j);d=np.array([-.11,.03,-.09]);
for damp in [0,.02,.05]:
 q=J.T@np.linalg.solve(J@J.T+damp**2*np.eye(3),d)
 print(damp,q.round(3), 'achieved', (J@q).round(3))
PY",yield_time_ms:10000,max_output_tokens:500}); text(r.output);

